ALTER TABLE issue_workflow_action_receipt ADD COLUMN lease_count INTEGER NOT NULL DEFAULT 0 CHECK (lease_count >= 0), ADD COLUMN effect_attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (effect_attempt_count >= 0), ADD COLUMN observation_failure_count INTEGER NOT NULL DEFAULT 0 CHECK (observation_failure_count >= 0), ADD COLUMN effect_key TEXT GENERATED ALWAYS AS (action_type || '/' || id::text) STORED, ADD COLUMN effect_result JSONB NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN reconciliation_state TEXT NOT NULL DEFAULT 'none' CHECK (reconciliation_state IN ('none', 'observing', 'found', 'absent', 'unknown', 'failed')), ADD COLUMN last_observed_at TIMESTAMPTZ, ADD COLUMN bound_task_id UUID;
